#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ilen = 0, ipos = 0;

static inline int gc() {
    if (ipos == ilen) {
        ilen = fread(ibuf, 1, sizeof ibuf, stdin);
        ipos = 0;
        if (ilen == 0) return -1;
    }
    return ibuf[ipos++];
}

static long long readInt() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    bool neg = c == '-';
    if (neg) c = gc();
    long long v = 0;
    while (c >= '0' && c <= '9') {
        v = v * 10 + (c - '0');
        c = gc();
    }
    return neg ? -v : v;
}

static string readToken() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    string s;
    while (c > ' ') {
        s.push_back((char)c);
        c = gc();
    }
    return s;
}

int main() {
    int n = (int)readInt();
    long long k = readInt();
    int m = (int)readInt();
    vector<long long> a(n), costs(n);
    for (auto &x : a) x = readInt();
    long long answer = 0;
    for (int b = 30; b >= 0; b--) {
        long long mask = answer | (1LL << b);
        for (int i = 0; i < n; i++) {
            long long x = a[i], missing = mask & ~x;
            if (!missing) {
                costs[i] = 0;
                continue;
            }
            int bit = 63 - __builtin_clzll(missing);
            // Smallest y >= x that contains every bit of mask: keep the prefix above `bit`,
            // set `bit`, then only the lower mask bits.
            long long y = ((x >> (bit + 1)) << (bit + 1)) | (1LL << bit) | (mask & ((1LL << bit) - 1));
            costs[i] = y - x;
        }
        sort(costs.begin(), costs.end());
        long long sum = 0;
        for (int i = 0; i < m; i++) sum += costs[i];
        if (sum <= k) answer = mask;
    }
    printf("%lld\n", answer);
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

