package main

import (
	"fmt"
	"io"
	"math/bits"
	"os"
	"sort"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k, m := nextInt(), nextInt(), nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	costs := make([]int, n)
	answer := 0
	for b := 30; b >= 0; b-- {
		mask := answer | 1<<b
		for i, x := range a {
			missing := mask &^ x
			if missing == 0 {
				costs[i] = 0
				continue
			}
			bit := bits.Len(uint(missing)) - 1
			y := (x>>(bit+1))<<(bit+1) | 1<<bit | mask&(1<<bit-1)
			costs[i] = y - x
		}
		sort.Ints(costs)
		sum := 0
		for i := 0; i < m; i++ {
			sum += costs[i]
		}
		if sum <= k {
			answer = mask
		}
	}
	fmt.Println(answer)
}
